func isStd(pkg string) bool {
	return stdPkgs[pkg]
}

func isCompany(pkg string, prefixes string) bool {
	if prefixes == "" {
		return false
	}
	for _, p := range strings.Split(prefixes, ",") {
		p = strings.TrimSpace(p)
		if p == "" {
			continue
		}
		if pkg == p || strings.HasPrefix(pkg, p+"/") {
			return true
		}
	}
	return false
}

func isProject(pkg string, project string) bool {
	if project == "" {
		return false
	}
	return pkg == project || strings.HasPrefix(pkg, project+"/")
}

func isVersion(s string) bool {
	if len(s) < 2 || s[0] != 'v' {
		return false
	}
	for _, c := range s[1:] {
		if c < '0' || c > '9' {
			if c == '.' {
				continue
			}
			return false
		}
	}
	return true
}

func isVersionedPath(p string) bool {
	parts := strings.Split(p, "/")
	if len(parts) == 0 {
		return false
	}
	return isVersion(parts[len(parts)-1])
}

func getAliasForVersioned(p string) string {
	parts := strings.Split(p, "/")
	if len(parts) >= 2 && isVersion(parts[len(parts)-1]) {
		return parts[len(parts)-2]
	}
	return parts[len(parts)-1]
}

func isGenerated(content string) bool {
	lines := strings.Split(content, "\n")
	for _, line := range lines {
		trimmedLeft := strings.TrimLeft(line, " \t")
		if trimmedLeft == "" {
			continue
		}
		if strings.HasPrefix(trimmedLeft, "package ") {
			break
		}
		if strings.HasPrefix(trimmedLeft, "//") {
			if strings.HasPrefix(trimmedLeft, "// Code generated ") && strings.HasSuffix(trimmedLeft, "DO NOT EDIT.") && len(trimmedLeft) > len("// Code generated ")+len("DO NOT EDIT.") {
				return true
			}
		} else {
			// non-comment line before package (e.g., /* */) ignore
			continue
		}
	}
	return false
}

func findProjectName(startPath string) (string, error) {
	var dir string
	fi, err := os.Stat(startPath)
	if err == nil && fi.IsDir() {
		dir = startPath
	} else {
		dir = filepath.Dir(startPath)
	}
	for {
		gomod := filepath.Join(dir, "go.mod")
		data, err := os.ReadFile(gomod)
		if err == nil {
			lines := strings.Split(string(data), "\n")
			for _, l := range lines {
				l = strings.TrimSpace(l)
				if strings.HasPrefix(l, "module ") {
					mod := strings.TrimSpace(strings.TrimPrefix(l, "module"))
					// Trim quotes?
					mod = strings.Trim(mod, "\"")
					return mod, nil
				}
			}
			// found go.mod but no module line? treat as not found?
			return "", fmt.Errorf("open go.mod: no such file or directory")
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			break
		}
		dir = parent
		// stop at filesystem root or when dir is "." and no go.mod
		if dir == "." && startPath != "." && !strings.HasPrefix(startPath, "./") && !strings.HasPrefix(startPath, "/") {
			// For relative paths like /tmp/... absolute will have dir as /tmp
		}
	}
	return "", fmt.Errorf("open go.mod: no such file or directory")
}

func isExcluded(filePath, baseDir, excludes string) bool {
	if excludes == "" {
		return false
	}
	patterns := strings.Split(excludes, ",")
	rel := ""
	if baseDir != "" {
		if r, err := filepath.Rel(baseDir, filePath); err == nil {
			rel = r
		} else {
			rel = filePath
		}
		rel = filepath.ToSlash(rel)
	}
	filePathSlash := filepath.ToSlash(filePath)
	for _, pat := range patterns {
		pat = strings.TrimSpace(pat)
		if pat == "" {
			continue
		}
		patSlash := filepath.ToSlash(pat)
		// Direct match via filepath.Match on rel and on filePath
		if matched, _ := filepath.Match(patSlash, rel); matched {
			return true
		}
		if matched, _ := filepath.Match(patSlash, filePathSlash); matched {
			return true
		}
		if matched, _ := filepath.Match(patSlash, path.Base(filePathSlash)); matched {
			return true
		}
		// Suffix match for sub pattern
		if strings.HasSuffix(filePathSlash, patSlash) {
			return true
		}
		if strings.HasSuffix(filePathSlash, "/"+patSlash) {
			return true
		}
		if strings.HasSuffix(rel, patSlash) {
			return true
		}
		if strings.HasSuffix(rel, "/"+patSlash) {
			return true
		}
		// Directory pattern ending with "/"
		if strings.HasSuffix(patSlash, "/") {
			if strings.Contains(filePathSlash, patSlash) {
				return true
			}
			if strings.Contains(rel, patSlash) {
				return true
			}
		} else {
			// Also check if pattern contains "/" and rel has prefix
			if strings.Contains(patSlash, "/") {
				// For pat like "proto/*.go", try match on rel
				if matched, _ := path.Match(patSlash, rel); matched {
					return true
				}
				if matched, _ := path.Match(patSlash, filePathSlash); matched {
					return true
				}
			}
			// Substring for directory exclusion like ".git"
			if strings.Contains(filePathSlash, "/"+patSlash+"/") || strings.HasSuffix(filePathSlash, "/"+patSlash) || filePathSlash == patSlash {
				// This would overmatch, but for ".git" pattern we want to match .git directory
				// However earlier test showed ".git/" didn't exclude, but this would exclude
				// To match original behavior where ".git/" didn't exclude, we should require trailing slash handling above only
				// So not here
			}
		}
		// For pattern like "sub/*.go", also check if rel matches via path.Match
		if strings.Contains(patSlash, "*") {
			if matched, _ := path.Match(patSlash, rel); matched {
				return true
			}
		}
	}
	return false
}

type impInfo struct {
	Alias   string
	Path    string
	Comment *ast.CommentGroup
	Doc     *ast.CommentGroup
}

func formatImportLine(imp impInfo) string {
	var sb strings.Builder
	sb.WriteString("\t")
	if imp.Alias != "" {
		sb.WriteString(imp.Alias)
		sb.WriteString(" ")
	}
	sb.WriteString(strconv.Quote(imp.Path))
	if imp.Comment != nil && len(imp.Comment.List) > 0 {
		for _, c := range imp.Comment.List {
			sb.WriteString(" ")
			sb.WriteString(c.Text)
		}
	}
	return sb.String()
}

func classifyAndSort(imports []impInfo, opts Options) ([]string, map[string][]impInfo) {
	orderRaw := opts.ImportsOrder
	if orderRaw == "" {
		orderRaw = "std,general,company,project"
	}
	order := strings.Split(orderRaw, ",")
	for i, v := range order {
		order[i] = strings.TrimSpace(v)
	}
	orderSet := make(map[string]bool)
	for _, g := range order {
		orderSet[g] = true
	}
	groups := make(map[string][]impInfo)
	for _, imp := range imports {
		var g string
		alias := imp.Alias
		path := imp.Path
		if alias == "_" && orderSet["blanked"] {
			g = "blanked"
		} else if alias == "." && orderSet["dotted"] {
			g = "dotted"
		} else {
			if isStd(path) {
				g = "std"
			} else if isCompany(path, opts.CompanyPrefixes) {
				g = "company"
			} else if isProject(path, opts.ProjectName) {
				g = "project"
			} else {
				g = "general"
			}
			if _, ok := orderSet[g]; !ok {
				// fallback to general
				g = "general"
			}
			// If blanked/dotted but order doesn't contain, they already fell through to general
		}
		// If g is blanked/dotted but order doesn't contain, they would have been handled above? Actually they would have been general.
		// If g not in orderSet (e.g., company when order doesn't have company), fallback already.
		if _, ok := orderSet[g]; !ok {
			g = "general"
		}
		groups[g] = append(groups[g], imp)
	}
	// Ensure every group in order exists in map
	for _, g := range order {
		if _, ok := groups[g]; !ok {
			groups[g] = nil
		}
	}
	return order, groups
}

func findUsedImports(f *ast.File, imports []impInfo) map[string]bool {
	used := make(map[string]bool)
	ast.Inspect(f, func(n ast.Node) bool {
		switch x := n.(type) {
		case *ast.SelectorExpr:
			if ident, ok := x.X.(*ast.Ident); ok {
				used[ident.Name] = true
			}
		case *ast.Ident:
			// For handling import used as value? Not needed
		}
		return true
	})
	// Also check for *ast.ImportSpec usage via types? Not needed.
	return used
}

func processFileContent(filePath string, content []byte, opts Options) ([]byte, bool, error) {
	origStr := string(content)
	if !opts.ApplyToGenerated && isGenerated(origStr) {
		// Skip processing
		return content, false, nil
	}
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, filePath, content, parser.ParseComments)
	if err != nil {
		return nil, false, fmt.Errorf("file has invalid Go source content, use -excludes flag to skip this file: %s", err)
	}
	// Collect specs
	var allSpecs []*ast.ImportSpec
	var importDecls []*ast.GenDecl
	for _, decl := range f.Decls {
		if gen, ok := decl.(*ast.GenDecl); ok && gen.Tok == token.IMPORT {
			importDecls = append(importDecls, gen)
			for _, spec := range gen.Specs {
				allSpecs = append(allSpecs, spec.(*ast.ImportSpec))
			}
		}
	}
	// If no imports, handle formatting only?
	if len(allSpecs) == 0 {
		// Still need to handle format?
		if opts.Format {
			formatted, err := format.Source(content)
			if err != nil {
				return nil, false, err
			}
			changed := !bytes.Equal(formatted, content)
			return formatted, changed, nil
		}
		// For no imports, just return content as is (maybe format via printer? but we will handle via format if needed)
		// Check if formatting would change due to import sorting no.
		return content, false, nil
	}
	// Build impInfo slice
	var imports []impInfo
	for _, s := range allSpecs {
		alias := ""
		if s.Name != nil {
			alias = s.Name.Name
		}
		path, _ := strconv.Unquote(s.Path.Value)
		imports = append(imports, impInfo{
			Alias:   alias,
			Path:    path,
			Comment: s.Comment,
			Doc:     s.Doc,
		})
	}
	// rmUnused
	if opts.RmUnused {
		used := findUsedImports(f, imports)
		var filtered []impInfo
		for _, imp := range imports {
			if imp.Alias == "_" || imp.Alias == "." {
				filtered = append(filtered, imp)
				continue
			}
			name := imp.Alias
			if name == "" {
				// derive from path
				base := path.Base(imp.Path)
				if isVersion(base) {
					parts := strings.Split(imp.Path, "/")
					if len(parts) >= 2 {
						base = parts[len(parts)-2]
					}
				}
				name = base
			}
			if used[name] {
				filtered = append(filtered, imp)
			} else {
				// Check if import is used via blank identifier? Already handled
				// Also check if the import path is used as import alias with different name? No
			}
		}
		imports = filtered
	}
	// setAlias
	if opts.SetAlias {
		for i, imp := range imports {
			if imp.Alias != "" {
				continue
			}
			if isVersionedPath(imp.Path) {
				alias := getAliasForVersioned(imp.Path)
				imports[i].Alias = alias
			}
		}
	}
	// If after filtering no imports, need to remove import block
	if len(imports) == 0 {
		// Find import range and remove
		// Use fset to find offsets
		if len(importDecls) > 0 {
			file := fset.File(f.Pos())
			firstPos := importDecls[0].Pos()
			lastPos := importDecls[len(importDecls)-1].End()
			firstOff := file.Offset(firstPos)
			lastOff := file.Offset(lastPos)
			newStr := origStr[:firstOff] + strings.TrimSpace(origStr[lastOff:]) // need to handle?
			// Find package line end and ensure no extra blank lines?
			// Simple: remove import block and ensure one newline
			// Use string replacement with proper handling
			before := origStr[:firstOff]
			after := origStr[lastOff:]
			// Trim leading newlines from after?
			newContentStr := before + after
			// Format if needed
			if opts.Format {
				formatted, err := format.Source([]byte(newContentStr))
				if err != nil {
					return nil, false, err
				}
				changed := !bytes.Equal(formatted, content)
				return formatted, changed, nil
			}
			// For non-format, just return newStr formatted via gofmt? Use format.Source as well to clean up?
			// The tool still formats even without -format for import removal? earlier test showed without -format still formats.
			formatted, err := format.Source([]byte(newContentStr))
			if err != nil {
				// Try printer
				return []byte(newContentStr), true, nil
			}
			// For non-format, we might want to not add blank lines, but format.Source will add
			// We'll handle later
			if !opts.Format {
				// Collapse blank lines between funcs as earlier
				s := string(formatted)
				s = strings.ReplaceAll(s, "}\n\nfunc", "}\nfunc")
				formatted = []byte(s)
			}
			changed := !bytes.Equal(formatted, content)
			return formatted, changed, nil
		}
		return content, false, nil
	}
	// Classify and sort
	order, groups := classifyAndSort(imports, opts)
	// Build lines with grouping
	var lines []string
	// For checking hasNext
	for idx, gName := range order {
		list := groups[gName]
		if len(list) == 0 {
			continue
		}
		// Sort within group
		if opts.SeparateNamed {
			var unnamed, named []impInfo
			for _, imp := range list {
				if imp.Alias != "" && imp.Alias != "_" && imp.Alias != "." {
					named = append(named, imp)
				} else {
					unnamed = append(unnamed, imp)
				}
			}
			sort.Slice(unnamed, func(a, b int) bool { return unnamed[a].Path < unnamed[b].Path })
			sort.Slice(named, func(a, b int) bool { return named[a].Path < named[b].Path })
			// Generate lines for unnamed then named
			for _, imp := range unnamed {
				lines = append(lines, formatImportLine(imp))
			}
			if len(unnamed) > 0 && len(named) > 0 {
				lines = append(lines, "")
			}
			for _, imp := range named {
				lines = append(lines, formatImportLine(imp))
			}
		} else {
			sort.Slice(list, func(a, b int) bool { return list[a].Path < list[b].Path })
			for _, imp := range list {
				lines = append(lines, formatImportLine(imp))
			}
		}
		// Check if there is next non-empty group
		hasNext := false
		for j := idx + 1; j < len(order); j++ {
			if len(groups[order[j]]) > 0 {
				hasNext = true
				break
			}
		}
		if hasNext {
			lines = append(lines, "")
		}
	}
	// Generate new block string
	var newBlock string
	if len(lines) == 1 && lines[0] != "" {
		// Single import, output as single line
		trimmed := strings.TrimSpace(lines[0])
		newBlock = "import " + trimmed + "\n"
	} else if len(lines) > 0 {
		// Remove trailing empty lines if any
		for len(lines) > 0 && lines[len(lines)-1] == "" {
			lines = lines[:len(lines)-1]
		}
		newBlock = "import (\n" + strings.Join(lines, "\n") + "\n)\n"
	} else {
		newBlock = ""
	}
	// Find import range offsets
	file := fset.File(f.Pos())
	firstPos := importDecls[0].Pos()
	lastPos := importDecls[len(importDecls)-1].End()
	firstOff := file.Offset(firstPos)
	lastOff := file.Offset(lastPos)
	// Ensure we handle case where there are multiple import decls not contiguous: the range from first to last includes code between them, which we would incorrectly remove.
	// Instead, we should replace each decl individually, but simpler to replace from first to last if they are contiguous at top.
	// For typical files, imports are at top, contiguous. We'll assume.
	newStr := origStr[:firstOff] + newBlock + origStr[lastOff:]
	// Handle formatting
	var formatted []byte
	if opts.Format {
		fmtd, err := format.Source([]byte(newStr))
		if err != nil {
			// Fallback to printer
			// Use printer on f with new decls? But we already did string replacement.
			// Try to format via printer
			var buf bytes.Buffer
			cfg := printer.Config{Mode: printer.TabIndent | printer.UseSpaces, Tabwidth: 8}
			// Need to create new file with updated decls and print
			// For fallback, just return newStr
			_ = cfg
			_ = buf
			return []byte(newStr), true, nil
		}
		formatted = fmtd
	} else {
		// Without format, still need to format import block but not necessarily whole file
		// We'll run format.Source and then post-process to remove extra blank lines between funcs
		fmtd, err := format.Source([]byte(newStr))
		if err != nil {
			return []byte(newStr), true, nil
		}
		formatted = fmtd
		// Post-process for non-format: collapse blank lines between funcs where previous is }
		s := string(formatted)
		// Only collapse "}\n\nfunc" to "}\nfunc"
		s = strings.ReplaceAll(s, "}\n\nfunc", "}\nfunc")
		// Also handle other decls: "}\n\ntype" etc. but keep import's ")\n\nfunc" as is
		// The above replace will affect only "}\n\nfunc", not ")\n\nfunc"
		formatted = []byte(s)
	}
	changed := !bytes.Equal(formatted, content)
	// For idempotency, if not changed, return original
	if !changed {
		return content, false, nil
	}
	return formatted, true, nil
}

func collectFiles(paths []string, recursive bool, excludes string, applyToGenerated bool) ([]string, []string, error) {
	var files []string
	var dirs []string // to track which args were directories
	for _, p := range paths {
		// Check for ... pattern
		if strings.Contains(p, "...") {
			// Treat as pattern
			base := strings.TrimSuffix(p, "/...")
			base = strings.TrimSuffix(base, "...")
			base = strings.TrimSuffix(base, "/")
			if base == "" {
				base = "."
			}
			// Walk base recursively
			err := filepath.Walk(base, func(path string, info os.FileInfo, err error) error {
				if err != nil {
					return err
				}
				if info.IsDir() {
					// Check if dir is excluded
					if isExcluded(path, base, excludes) {
						return filepath.SkipDir
					}
					return nil
				}
				if strings.HasSuffix(path, ".go") {
					if !isExcluded(path, base, excludes) {
						files = append(files, path)
					}
				}
				return nil
			})
			if err != nil {
				return nil, nil, err
			}
			dirs = append(dirs, p)
			continue
		}
		fi, err := os.Stat(p)
		if err != nil {
			return nil, nil, err
		}
		if fi.IsDir() {
			dirs = append(dirs, p)
			if recursive {
				err := filepath.Walk(p, func(path string, info os.FileInfo, err error) error {
					if err != nil {
						return err
					}
					if info.IsDir() {
						if isExcluded(path, p, excludes) {
							return filepath.SkipDir
						}
						return nil
					}
					if strings.HasSuffix(path, ".go") {
						if !isExcluded(path, p, excludes) {
							files = append(files, path)
						}
					}
					return nil
				})
				if err != nil {
					return nil, nil, err
				}
			} else {
				// Only top-level
				entries, err := os.ReadDir(p)
				if err != nil {
					return nil, nil, err
				}
				for _, e := range entries {
					if e.IsDir() {
						continue
					}
					if strings.HasSuffix(e.Name(), ".go") {
						fp := filepath.Join(p, e.Name())
						if !isExcluded(fp, p, excludes) {
							files = append(files, fp)
						}
					}
				}
			}
		} else {
			// Single file
			// Check if file is excluded? Original didn't exclude single file, but we will not check
			files = append(files, p)
		}
	}
	return files, dirs, nil
}

