	}

	// Check for invalid output value? Assume valid

	// Collect files
	files, dirs, err := collectFiles(args, opts.Recursive, opts.Excludes, opts.ApplyToGenerated)
	if err != nil {
		// For errors like open .../... no such file
		// Original prints "Failed to fix file: open ..."
		// But for project name not found, it prints usage then error
		// Determine error type
		if strings.Contains(err.Error(), "no such file or directory") && strings.Contains(args[0], "...") {
			log.Printf("Failed to fix file: open %s: no such file or directory", args[0])
			if deprecatedExit {
				os.Exit(1)
			}
			if opts.SetExitStatus {
				os.Exit(1)
			}
			os.Exit(1)
		}
		// For other stat errors (file not found)
		// Check if it's file not found for single file
		// Original for /nonexistent printed usage then project name error, not Failed to fix
		// But for pattern ... it printed Failed to fix
		// We'll handle project name case separately
		// For now, treat as Failed to fix
		log.Printf("Failed to fix file: %v", err)
		os.Exit(1)
	}

	// If files empty (e.g., empty dir), need to handle project name error?
	if len(files) == 0 {
		// Check project name for first arg
		if opts.ProjectName == "" {
			// Try to find project name for first arg
			_, err := findProjectName(args[0])
			if err != nil {
				flag.Usage()
				log.Printf("Could not determine project name for path %s: %v", args[0], err)
				os.Exit(1)
			}
		}
		// No files to process, exit 0?
		if deprecatedExit {
			os.Exit(1)
		}
		os.Exit(0)
	}

	// Determine if args were directories (for output handling)
	isDirArg := len(dirs) > 0
	// Also if any arg is directory, treat as dir mode for output?
	// For simplicity, if any dir arg, treat as dir mode
	isDirMode := isDirArg
	// But also if args contain multiple files, isDirMode false but multiple files handling similar to dir?

	// Need to determine projectName if not provided
	if opts.ProjectName == "" {
		// Try to find for first file
		proj, err := findProjectName(files[0])
		if err != nil {
			flag.Usage()
			// Use first arg path for error message (original uses path from args[0])
			log.Printf("Could not determine project name for path %s: %v", args[0], err)
			os.Exit(1)
		}
		opts.ProjectName = proj
	}

	// Also need to handle case where files are from different modules? Use first project's name for all
	// For each file, if its own project differs, maybe use file's own? But we use global
	// Original seems to determine per path, but we will use global

	overallChanged := false
	overallError := false

	// For handling output with multiple files and list-diff stdout, we need to know total files count
	for _, file := range files {
		content, err := os.ReadFile(file)
		if err != nil {
			log.Printf("Failed to fix file: open %s: no such file or directory", file)
			overallError = true
			continue
		}
		newContent, changed, procErr := processFileContent(file, content, opts)
		if procErr != nil {
			// Check error type
			if strings.Contains(procErr.Error(), "file has invalid Go source") {
				log.Printf("Failed to fix file: %v", procErr)
				overallError = true
				continue
			} else {
				log.Printf("Failed to fix file: %v", procErr)
				overallError = true
				continue
			}
		}
		if changed {
			overallChanged = true
		}

		// Output handling
		if opts.ListDiff {
			if isDirMode {
				// Directory mode with list-diff: only list files that changed
				if changed {
					fmt.Fprintln(os.Stdout, file)
					if opts.Output == "write" {
						// Write file
						_ = os.WriteFile(file, newContent, 0644)
					}
				} else {
					// For directory, don't output anything for unchanged
					// But earlier we saw for directory non-recursive, unchanged files were not listed, correct
				}
			} else {
				// Single file or multiple files (non-dir)
				if len(files) == 1 {
					// Single file
					if changed {
						fmt.Fprintln(os.Stdout, file)
						if opts.Output == "write" {
							_ = os.WriteFile(file, newContent, 0644)
						}
					} else {
						if opts.Output == "stdout" {
							// Print formatted content
							_, _ = os.Stdout.Write(newContent)
						} else {
							// For output file/write with no change, still print filename (as observed)
							fmt.Fprintln(os.Stdout, file)
						}
					}
				} else {
					// Multiple files
					if changed {
						fmt.Fprintln(os.Stdout, file)
						if opts.Output == "write" {
							_ = os.WriteFile(file, newContent, 0644)
						}
					} else {
						if opts.Output == "stdout" {
							// For multiple files with stdout and not changed, what to print?
							// Observed for both done files with stdout, they printed formatted contents concatenated
							// For need then done with stdout, need printed filename, done printed filename (if both considered changed)
							// For done then need, done printed content, need printed filename
							// So for multiple files, if not changed and output stdout, print formatted content
							// If not changed and output file/write, print filename
							_, _ = os.Stdout.Write(newContent)
							// But earlier we saw for both need+done with stdout, done printed filename when need first. Hmm
							// Let's follow rule: if changed, print filename; else if output stdout, print content; else print filename
							// For multiple files case where we have both changed and not changed, this would intermix
							// We'll implement: if opts.Output == "stdout" {
							//   print content
							// } else {
							//   print filename
							// }
							// But our earlier branch for changed already handled stdout as filename, which conflicts
							// For multiple files, changed with stdout should print filename, not content, as observed for need file
							// So for changed with stdout and multiple files, still filename
							// For not changed with stdout and multiple files, print content
							// That matches earlier: need (changed) => filename, done (not changed) => content
							// But earlier both need+done with stdout where need first gave both filenames, not content for done. So that would be inconsistent.
							// Maybe that case's done was actually considered changed (since file not exactly formatted), so both were changed
						} else {
							fmt.Fprintln(os.Stdout, file)
						}
					}
				}
			}
		} else {
			// No list-diff
			if isDirMode {
				// Directory mode: always write file if changed, stdout empty
				if changed {
					_ = os.WriteFile(file, newContent, 0644)
				} else {
					// Even if not changed, file is already formatted, no need to write
					// But original for directory without list-diff and output stdout still wrote file if changed, else not
				}
			} else {
				// File mode
				if len(files) == 1 {
					if opts.Output == "stdout" {
						_, _ = os.Stdout.Write(newContent)
					} else {
						// file or write
						if changed {
							_ = os.WriteFile(file, newContent, 0644)
						} else {
							// Even if not changed, file is already formatted, but we still write? In earlier test, single done with output file and no list-diff, file remained same, stdout empty, exit 0
							// So we don't need to write if not changed
						}
					}
				} else {
					// Multiple files, no list-diff, output stdout => print concatenated formatted
					if opts.Output == "stdout" {
						_, _ = os.Stdout.Write(newContent)
					} else {
						if changed {
							_ = os.WriteFile(file, newContent, 0644)
						}
					}
				}
			}
		}
	}

	if overallError {
		os.Exit(1)
	}
	if deprecatedExit {
		os.Exit(1)
	}
	if opts.SetExitStatus && overallChanged {
		os.Exit(1)
	}
	// For other cases, exit 0
}

GO
"}

