func isStd(pkg string) bool {
	return stdPkgs[pkg]
}

func isCompany(pkg string, prefixes string) bool {
	if prefixes == "" {
		return false
	}
	for _, p := range strings.Split(prefixes, ",") {
		p = strings.TrimSpace(p)
		if p == "" {
			continue
		}
		if pkg == p || strings.HasPrefix(pkg, p+"/") {
			return true
		}
	}
	return false
}

func isProject(pkg string, project string) bool {
	if project == "" {
		return false
	}
	return pkg == project || strings.HasPrefix(pkg, project+"/")
}

func isVersion(s string) bool {
	if len(s) < 2 || s[0] != 'v' {
		return false
	}
	for _, c := range s[1:] {
		if c < '0' || c > '9' {
			if c == '.' {
				continue
			}
			return false
		}
	}
	return true
}

func isVersionedPath(p string) bool {
	parts := strings.Split(p, "/")
	if len(parts) == 0 {
		return false
	}
	return isVersion(parts[len(parts)-1])
}

func getAliasForVersioned(p string) string {
	parts := strings.Split(p, "/")
	if len(parts) >= 2 && isVersion(parts[len(parts)-1]) {
		return parts[len(parts)-2]
	}
	return parts[len(parts)-1]
}

func isGenerated(content string) bool {
	lines := strings.Split(content, "\n")
	for _, line := range lines {
		trimmedLeft := strings.TrimLeft(line, " \t")
		if trimmedLeft == "" {
			continue
		}
		if strings.HasPrefix(trimmedLeft, "package ") {
			break
		}
		if strings.HasPrefix(trimmedLeft, "//") {
			if strings.HasPrefix(trimmedLeft, "// Code generated ") && strings.HasSuffix(trimmedLeft, "DO NOT EDIT.") && len(trimmedLeft) > len("// Code generated ")+len("DO NOT EDIT.") {
				return true
			}
		} else {
			continue
		}
	}
	return false
}

func findProjectName(startPath string) (string, error) {
	var dir string
	fi, err := os.Stat(startPath)
	if err == nil && fi.IsDir() {
		dir = startPath
	} else {
		dir = filepath.Dir(startPath)
	}
	for {
		gomod := filepath.Join(dir, "go.mod")
		data, err := os.ReadFile(gomod)
		if err == nil {
			lines := strings.Split(string(data), "\n")
			for _, l := range lines {
				l = strings.TrimSpace(l)
				if strings.HasPrefix(l, "module ") {
					mod := strings.TrimSpace(strings.TrimPrefix(l, "module"))
					mod = strings.Trim(mod, "\"")
					return mod, nil
				}
			}
			return "", fmt.Errorf("open go.mod: no such file or directory")
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			break
		}
		dir = parent
	}
	return "", fmt.Errorf("open go.mod: no such file or directory")
}

func isExcluded(filePath, baseDir, excludes string) bool {
	if excludes == "" {
		return false
	}
	patterns := strings.Split(excludes, ",")
	rel := ""
	if baseDir != "" {
		if r, err := filepath.Rel(baseDir, filePath); err == nil {
			rel = r
		} else {
			rel = filePath
		}
		rel = filepath.ToSlash(rel)
	}
	filePathSlash := filepath.ToSlash(filePath)
	for _, pat := range patterns {
		pat = strings.TrimSpace(pat)
		if pat == "" {
			continue
		}
		patSlash := filepath.ToSlash(pat)
		if matched, _ := filepath.Match(patSlash, rel); matched {
			return true
		}
		if matched, _ := filepath.Match(patSlash, filePathSlash); matched {
			return true
		}
		if matched, _ := filepath.Match(patSlash, path.Base(filePathSlash)); matched {
			return true
		}
		if strings.HasSuffix(filePathSlash, patSlash) {
			return true
		}
		if strings.HasSuffix(filePathSlash, "/"+patSlash) {
			return true
		}
		if strings.HasSuffix(rel, patSlash) {
			return true
		}
		if strings.HasSuffix(rel, "/"+patSlash) {
			return true
		}
		if strings.HasSuffix(patSlash, "/") {
			if strings.Contains(filePathSlash, patSlash) {
				return true
			}
			if strings.Contains(rel, patSlash) {
				return true
			}
		} else {
			if strings.Contains(patSlash, "/") {
				if matched, _ := path.Match(patSlash, rel); matched {
					return true
				}
				if matched, _ := path.Match(patSlash, filePathSlash); matched {
					return true
				}
			}
		}
		if strings.Contains(patSlash, "*") {
			if matched, _ := path.Match(patSlash, rel); matched {
				return true
			}
		}
	}
	return false
}

type impInfo struct {
	Alias   string
	Path    string
	Comment *ast.CommentGroup
	Doc     *ast.CommentGroup
}

func formatImportLine(imp impInfo) string {
	var sb strings.Builder
	sb.WriteString("\t")
	if imp.Alias != "" {
		sb.WriteString(imp.Alias)
		sb.WriteString(" ")
	}
	sb.WriteString(strconv.Quote(imp.Path))
	if imp.Comment != nil && len(imp.Comment.List) > 0 {
		for _, c := range imp.Comment.List {
			sb.WriteString(" ")
			sb.WriteString(c.Text)
		}
	}
	return sb.String()
}

func classifyAndSort(imports []impInfo, opts Options) ([]string, map[string][]impInfo) {
	orderRaw := opts.ImportsOrder
	if orderRaw == "" {
		orderRaw = "std,general,company,project"
	}
	order := strings.Split(orderRaw, ",")
	for i, v := range order {
		order[i] = strings.TrimSpace(v)
	}
	orderSet := make(map[string]bool)
	for _, g := range order {
		orderSet[g] = true
	}
	groups := make(map[string][]impInfo)
	for _, imp := range imports {
		var g string
		alias := imp.Alias
		path := imp.Path
		if alias == "_" && orderSet["blanked"] {
			g = "blanked"
		} else if alias == "." && orderSet["dotted"] {
			g = "dotted"
		} else {
			if isStd(path) {
				g = "std"
			} else if isCompany(path, opts.CompanyPrefixes) {
				g = "company"
			} else if isProject(path, opts.ProjectName) {
				g = "project"
			} else {
				g = "general"
			}
			if _, ok := orderSet[g]; !ok {
				g = "general"
			}
		}
		if _, ok := orderSet[g]; !ok {
			g = "general"
		}
		groups[g] = append(groups[g], imp)
	}
	for _, g := range order {
		if _, ok := groups[g]; !ok {
			groups[g] = nil
		}
	}
	return order, groups
}

func findUsedImports(f *ast.File, imports []impInfo) map[string]bool {
	used := make(map[string]bool)
	ast.Inspect(f, func(n ast.Node) bool {
		switch x := n.(type) {
		case *ast.SelectorExpr:
			if ident, ok := x.X.(*ast.Ident); ok {
				used[ident.Name] = true
			}
		}
		return true
	})
	return used
}

func processFileContent(filePath string, content []byte, opts Options) ([]byte, bool, error) {
	origStr := string(content)
	if !opts.ApplyToGenerated && isGenerated(origStr) {
		return content, false, nil
	}
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, filePath, content, parser.ParseComments)
	if err != nil {
		return nil, false, fmt.Errorf("file has invalid Go source content, use -excludes flag to skip this file: %s", err)
	}
	var allSpecs []*ast.ImportSpec
	var importDecls []*ast.GenDecl
	for _, decl := range f.Decls {
		if gen, ok := decl.(*ast.GenDecl); ok && gen.Tok == token.IMPORT {
			importDecls = append(importDecls, gen)
			for _, spec := range gen.Specs {
				allSpecs = append(allSpecs, spec.(*ast.ImportSpec))
			}
		}
	}
	if len(allSpecs) == 0 {
		if opts.Format {
			formatted, err := format.Source(content)
			if err != nil {
				return nil, false, err
			}
			changed := !bytes.Equal(formatted, content)
			return formatted, changed, nil
		}
		return content, false, nil
	}
	var imports []impInfo
	for _, s := range allSpecs {
		alias := ""
		if s.Name != nil {
			alias = s.Name.Name
		}
		path, _ := strconv.Unquote(s.Path.Value)
		imports = append(imports, impInfo{
			Alias:   alias,
			Path:    path,
			Comment: s.Comment,
			Doc:     s.Doc,
		})
	}
	if opts.RmUnused {
		used := findUsedImports(f, imports)
		var filtered []impInfo
		for _, imp := range imports {
			if imp.Alias == "_" || imp.Alias == "." {
				filtered = append(filtered, imp)
				continue
			}
			name := imp.Alias
			if name == "" {
				base := path.Base(imp.Path)
				if isVersion(base) {
					parts := strings.Split(imp.Path, "/")
					if len(parts) >= 2 {
						base = parts[len(parts)-2]
					}
				}
				name = base
			}
			if used[name] {
				filtered = append(filtered, imp)
			}
		}
		imports = filtered
	}
	if opts.SetAlias {
		for i, imp := range imports {
			if imp.Alias != "" {
				continue
			}
			if isVersionedPath(imp.Path) {
				alias := getAliasForVersioned(imp.Path)
				imports[i].Alias = alias
			}
		}
	}
	if len(imports) == 0 {
		if len(importDecls) > 0 {
			file := fset.File(f.Pos())
			firstPos := importDecls[0].Pos()
			lastPos := importDecls[len(importDecls)-1].End()
			firstOff := file.Offset(firstPos)
			lastOff := file.Offset(lastPos)
			before := origStr[:firstOff]
			after := origStr[lastOff:]
			newContentStr := before + after
			if opts.Format {
				formatted, err := format.Source([]byte(newContentStr))
				if err != nil {
					return nil, false, err
				}
				changed := !bytes.Equal(formatted, content)
				return formatted, changed, nil
			}
			formatted, err := format.Source([]byte(newContentStr))
			if err != nil {
				return []byte(newContentStr), true, nil
			}
			if !opts.Format {
				s := string(formatted)
				s = strings.ReplaceAll(s, "}\n\nfunc", "}\nfunc")
				formatted = []byte(s)
			}
			changed := !bytes.Equal(formatted, content)
			return formatted, changed, nil
		}
		return content, false, nil
	}
	order, groups := classifyAndSort(imports, opts)
	var lines []string
	for idx, gName := range order {
		list := groups[gName]
		if len(list) == 0 {
			continue
		}
		if opts.SeparateNamed {
			var unnamed, named []impInfo
			for _, imp := range list {
				if imp.Alias != "" && imp.Alias != "_" && imp.Alias != "." {
					named = append(named, imp)
				} else {
					unnamed = append(unnamed, imp)
				}
			}
			sort.Slice(unnamed, func(a, b int) bool { return unnamed[a].Path < unnamed[b].Path })
			sort.Slice(named, func(a, b int) bool { return named[a].Path < named[b].Path })
			for _, imp := range unnamed {
				lines = append(lines, formatImportLine(imp))
			}
			if len(unnamed) > 0 && len(named) > 0 {
				lines = append(lines, "")
			}
			for _, imp := range named {
				lines = append(lines, formatImportLine(imp))
			}
		} else {
			sort.Slice(list, func(a, b int) bool { return list[a].Path < list[b].Path })
			for _, imp := range list {
				lines = append(lines, formatImportLine(imp))
			}
		}
		hasNext := false
		for j := idx + 1; j < len(order); j++ {
			if len(groups[order[j]]) > 0 {
				hasNext = true
				break
			}
		}
		if hasNext {
			lines = append(lines, "")
		}
	}
	var newBlock string
	if len(lines) == 1 && lines[0] != "" {
		trimmed := strings.TrimSpace(lines[0])
		newBlock = "import " + trimmed + "\n"
	} else if len(lines) > 0 {
		for len(lines) > 0 && lines[len(lines)-1] == "" {
			lines = lines[:len(lines)-1]
		}
		newBlock = "import (\n" + strings.Join(lines, "\n") + "\n)\n"
	} else {
		newBlock = ""
	}
	file := fset.File(f.Pos())
	firstPos := importDecls[0].Pos()
	lastPos := importDecls[len(importDecls)-1].End()
	firstOff := file.Offset(firstPos)
	lastOff := file.Offset(lastPos)
	newStr := origStr[:firstOff] + newBlock + origStr[lastOff:]
	var formatted []byte
	if opts.Format {
		fmtd, err := format.Source([]byte(newStr))
		if err != nil {
			_ = printer.Config{}
			return []byte(newStr), true, nil
		}
		formatted = fmtd
	} else {
		fmtd, err := format.Source([]byte(newStr))
		if err != nil {
			return []byte(newStr), true, nil
		}
		formatted = fmtd
		s := string(formatted)
		s = strings.ReplaceAll(s, "}\n\nfunc", "}\nfunc")
		formatted = []byte(s)
	}
	changed := !bytes.Equal(formatted, content)
	if !changed {
		return content, false, nil
	}
	return formatted, true, nil
}

func collectFiles(paths []string, recursive bool, excludes string) ([]string, []string, error) {
	var files []string
	var dirs []string
	for _, p := range paths {
		if strings.Contains(p, "...") {
			base := strings.TrimSuffix(p, "/...")
			base = strings.TrimSuffix(base, "...")
			base = strings.TrimSuffix(base, "/")
			if base == "" {
				base = "."
			}
			err := filepath.Walk(base, func(pathStr string, info os.FileInfo, err error) error {
				if err != nil {
					return err
				}
				if info.IsDir() {
					if isExcluded(pathStr, base, excludes) {
						return filepath.SkipDir
					}
					return nil
				}
				if strings.HasSuffix(pathStr, ".go") {
					if !isExcluded(pathStr, base, excludes) {
						files = append(files, pathStr)
					}
				}
				return nil
			})
			if err != nil {
				return nil, nil, err
			}
			dirs = append(dirs, p)
			continue
		}
		fi, err := os.Stat(p)
		if err != nil {
			return nil, nil, err
		}
		if fi.IsDir() {
			dirs = append(dirs, p)
			if recursive {
				err := filepath.Walk(p, func(pathStr string, info os.FileInfo, err error) error {
					if err != nil {
						return err
					}
					if info.IsDir() {
						if isExcluded(pathStr, p, excludes) {
							return filepath.SkipDir
						}
						return nil
					}
					if strings.HasSuffix(pathStr, ".go") {
						if !isExcluded(pathStr, p, excludes) {
							files = append(files, pathStr)
						}
					}
					return nil
				})
				if err != nil {
					return nil, nil, err
				}
			} else {
				entries, err := os.ReadDir(p)
				if err != nil {
					return nil, nil, err
				}
				for _, e := range entries {
					if e.IsDir() {
						continue
					}
					if strings.HasSuffix(e.Name(), ".go") {
						fp := filepath.Join(p, e.Name())
						if !isExcluded(fp, p, excludes) {
							files = append(files, fp)
						}
					}
				}
			}
		} else {
			files = append(files, p)
		}
	}
	return files, dirs, nil
}

func main() {
	log.SetFlags(log.Ldate | log.Ltime)
	log.SetOutput(os.Stderr)

	var opts Options
	flag.BoolVar(&opts.ApplyToGenerated, "apply-to-generated-files", false, "Apply imports sorting and formatting(if the option is set) to generated files. Generated file is a file with first comment which starts with comment '// Code generated'. Optional parameter.")
	flag.StringVar(&opts.CompanyPrefixes, "company-prefixes", "", "Company package prefixes which will be placed after 3rd-party group by default(if defined). Values should be comma-separated. Optional parameters.")
	flag.StringVar(&opts.Excludes, "excludes", "", "Exclude files or dirs, example: '.git/,proto/*.go'.")
	flag.StringVar(&opts.FilePath, "file-path", "", "Deprecated. Put file name as an argument(last item) of command line.")
	flag.BoolVar(&opts.Format, "format", false, "Option will perform additional formatting. Optional parameter.")
	flag.StringVar(&opts.ImportsOrder, "imports-order", "std,general,company,project", "Your imports groups can be sorted in your way. \nstd - std import group; \ngeneral - libs for general purpose; \ncompany - inter-org or your company libs(if you set '-company-prefixes'-option, then 4th group will be split separately. In other case, it will be the part of general purpose libs); \nproject - your local project dependencies;\nblanked - imports with \"_\" alias;\ndotted - imports with \".\" alias.\nOptional parameter.")
	flag.BoolVar(&opts.ListDiff, "list-diff", false, "Option will list files whose formatting differs from goimports-reviser. Optional parameter.")
	flag.StringVar(&opts.Local, "local", "", "Deprecated")
	flag.StringVar(&opts.Output, "output", "file", "Can be \"file\", \"write\" or \"stdout\". Whether to write the formatted content back to the file or to stdout. When \"write\" together with \"-list-diff\" will list the file name and write back to the file. Optional parameter.")
	flag.StringVar(&opts.ProjectName, "project-name", "", "Your project name(ex.: github.com/incu6us/goimports-reviser). Optional parameter.")
	flag.BoolVar(&opts.Recursive, "recursive", false, "Apply rules recursively if target is a directory. In case of ./... execution will be recursively applied by default. Optional parameter.")
	flag.BoolVar(&opts.RmUnused, "rm-unused", false, "Remove unused imports. Optional parameter.")
	flag.BoolVar(&opts.SeparateNamed, "separate-named", false, "Separate named imports from their group with a new line. Optional parameter.")
	flag.BoolVar(&opts.SetAlias, "set-alias", false, "Set alias for versioned package names, like 'github.com/go-pg/pg/v9'. In this case import will be set as 'pg \"github.com/go-pg/pg/v9\"'. Optional parameter.")
	flag.BoolVar(&opts.SetExitStatus, "set-exit-status", false, "set the exit status to 1 if a change is needed/made. Optional parameter.")
	flag.BoolVar(&opts.UseCache, "use-cache", false, "Use cache to improve performance. Optional parameter.")
	flag.BoolVar(&opts.Version, "version", false, "Show version information")
	flag.BoolVar(&opts.VersionOnly, "version-only", false, "Show only the version string")
	flag.Parse()

	if opts.VersionOnly {
		fmt.Fprintln(os.Stdout, versionStr)
		os.Exit(0)
	}
	if opts.Version {
		fmt.Fprintf(os.Stdout, "version: %s\nbuilt with: %s\ntag: %s\ncommit: %s\nsource: %s\n", versionStr, builtWith, tagStr, commitStr, sourceStr)
		os.Exit(0)
	}

	args := flag.Args()
	deprecatedExit := false
	if opts.FilePath != "" {
		log.Println("-file-path is deprecated. Put file name(s) as last argument to the command(Example: goimports-reviser -rm-unused -set-alias -format goimports-reviser/main.go)")
		log.Println("All changes to file are applied, but command-line syntax should be fixed")
		args = append(args, opts.FilePath)
		deprecatedExit = true
	}
	if opts.Local != "" {
		log.Println("-local is deprecated and will be removed soon. Use -company-prefixes instead.")
		log.Println("All changes to file are applied, but command-line syntax should be fixed")
		if opts.CompanyPrefixes == "" {
			opts.CompanyPrefixes = opts.Local
		} else {
			opts.CompanyPrefixes = opts.CompanyPrefixes + "," + opts.Local
		}
		deprecatedExit = true
	}
	if len(args) == 0 {
		flag.Usage()
		log.Println("no file(s) or directory(ies) specified on input")
		os.Exit(1)
	}

	log.Printf("Paths: %v", args)
	for _, p := range args {
		log.Printf("Processing %s", p)
	}

	files, dirs, err := collectFiles(args, opts.Recursive, opts.Excludes)
	if err != nil {
		if strings.Contains(err.Error(), "no such file or directory") && strings.Contains(args[0], "...") {
			log.Printf("Failed to fix file: open %s: no such file or directory", args[0])
			if deprecatedExit {
				os.Exit(1)
			}
			if opts.SetExitStatus {
				os.Exit(1)
			}
			os.Exit(1)
		}
		log.Printf("Failed to fix file: %v", err)
		os.Exit(1)
	}

	if len(files) == 0 {
		if opts.ProjectName == "" {
			_, err := findProjectName(args[0])
			if err != nil {
				flag.Usage()
				log.Printf("Could not determine project name for path %s: %v", args[0], err)
				os.Exit(1)
			}
		}
		if deprecatedExit {
			os.Exit(1)
		}
		os.Exit(0)
	}

	isDirArg := len(dirs) > 0
	isDirMode := isDirArg

	if opts.ProjectName == "" {
		proj, err := findProjectName(files[0])
		if err != nil {
			flag.Usage()
			log.Printf("Could not determine project name for path %s: %v", args[0], err)
			os.Exit(1)
		}
		opts.ProjectName = proj
	}

	overallChanged := false
	overallError := false

	for _, file := range files {
		content, err := os.ReadFile(file)
		if err != nil {
			log.Printf("Failed to fix file: open %s: no such file or directory", file)
			overallError = true
			continue
		}
		newContent, changed, procErr := processFileContent(file, content, opts)
		if procErr != nil {
			if strings.Contains(procErr.Error(), "file has invalid Go source") {
				log.Printf("Failed to fix file: %v", procErr)
				overallError = true
				continue
			}
			log.Printf("Failed to fix file: %v", procErr)
			overallError = true
			continue
		}
		if changed {
			overallChanged = true
		}
		if opts.ListDiff {
			if isDirMode {
				if changed {
					fmt.Fprintln(os.Stdout, file)
					if opts.Output == "write" {
						_ = os.WriteFile(file, newContent, 0644)
					}
				}
			} else {
				if len(files) == 1 {
					if changed {
						fmt.Fprintln(os.Stdout, file)
						if opts.Output == "write" {
							_ = os.WriteFile(file, newContent, 0644)
						}
					} else {
						if opts.Output == "stdout" {
							_, _ = os.Stdout.Write(newContent)
						} else {
							fmt.Fprintln(os.Stdout, file)
						}
					}
				} else {
					if changed {
						fmt.Fprintln(os.Stdout, file)
						if opts.Output == "write" {
							_ = os.WriteFile(file, newContent, 0644)
						}
					} else {
						if opts.Output == "stdout" {
							_, _ = os.Stdout.Write(newContent)
						} else {
							fmt.Fprintln(os.Stdout, file)
						}
					}
				}
			}
		} else {
			if isDirMode {
				if changed {
					_ = os.WriteFile(file, newContent, 0644)
				}
			} else {
				if len(files) == 1 {
					if opts.Output == "stdout" {
						_, _ = os.Stdout.Write(newContent)
					} else {
						if changed {
							_ = os.WriteFile(file, newContent, 0644)
						}
					}
				} else {
					if opts.Output == "stdout" {
						_, _ = os.Stdout.Write(newContent)
					} else {
						if changed {
							_ = os.WriteFile(file, newContent, 0644)
						}
					}
				}
			}
		}
	}

	if overallError {
		os.Exit(1)
	}
	if deprecatedExit {
		os.Exit(1)
	}
	if opts.SetExitStatus && overallChanged {
		os.Exit(1)
	}
}
